"""
    f : funcion a integrar. Retorna un np.ndarray
    t : tiempo en el cual evaluar la funcion f
    y : para evaluar la funcion f
    paso : tamano del paso a usar.
    """
def k1(f: Any, t: Any, y: Any, paso: Any) -> object {
    output = paso * f(t, y);
    return output;
}

"""
    Function takes dictionary

    Evaluate values and convert string to correct type (boolean/int/float/long/string)
    """
def h_eval(data: Any) -> object {
    if isinstance(data, dict) {
        for _k in list(data.keys()) {
            data[_k] = h_eval(data[_k]);
            if ((data[_k] is None) or (isinstance(data[_k], dict) and not data[_k])) {
                data.pop(_k);
            }
        }
        return data;
    }
    if (
        isinstance(data, list) or isinstance(data, tuple) or isinstance(data, set)
    ) {
        res = [];
        for _k in data {
            res.append(h_eval(_k));
        }
        if isinstance(data, tuple) {
            return tuple(res);
        }
        if isinstance(data, set) {
            return set(res);
        }
        return res;
    }
    try {
        if isinstance(data, str) {
            if data.endswith("%") {
                data = data[:-1];
            }
            if (data.lower() == "false") {
                return False;
            }
            if (data.lower() == "true") {
                return True;
            }
            if (data.lower() == "n/e") {
                return None;
            }
            try {
                return int(data);
            } except Exception {
                ;
            }
            try {
                return float(data);
            } except Exception {
                ;
            }
        }
        return data;
    } except Exception {
        return data;
    }
}

"""Floor `n` to a multiple of `base`"""
def _floor(n: Any, base: Any = 1) -> object {
    return ((n // base) * base);
}

"""Skips leading whitespace and returns (i, indent),

    - i points after the whitespace
    - indent is the width of the whitespace, assuming tab_width wide tabs."""
def skip_leading_ws_with_indent(s: Any, i: Any, tab_width: Any) -> object {
    count = 0;
    n = len(s);
    while (i < n) {
        ch = s[i];
        if (ch == ' ') {
            count += 1;
            i += 1;
        } elif (ch == '\t') {
            count += abs(tab_width) - (count % abs(tab_width));
            i += 1;
        } else {
            break;
        }
    }
    return (i, count);
}

