"""
    converts s to an ascii string.

    s: unicode string
    """
def unicode_to_ascii(s: Any) -> object {
    ret = "";
    for ch in s {
        try {
            ach = str(ch);
            ret += ach;
        } except UnicodeEncodeError {
            ret += "?";
        }
    }
    return ret;
}

"""Return a good grid shape, in x,y, for a number if items i"""
def grid_shape(i: Any, max_x: Any = 4) -> object {
    import from math { sqrt, ceil }
    x = round(sqrt(i));
    if (x > max_x) {
        x = max_x;
    }
    y = ceil((i / x));
    return (x, y);
}

