"""Extract the literals from a cnf formula

    Parameters
    ----------
    cnf :list[set[(string,bool)]]
        The cnf from wich we want to extract the literla

    Returns
    -----
    set[str]
        set of the literals in the cnf
    """
def get_literals(cnf: Any) -> object {
    literals = set();
    for conj in cnf {
        for disj in conj {
            literals.add(disj[0]);
        }
    }
    return literals;
}

"""Computes the sum of all the multiples of 3 or 5 below the given limit,
    using tail recursion.

    :param limit: Limit of the values to sum (exclusive).
    :return: Sum of all the multiples of 3 or 5 below the given limit.
    """
def multiples_of_3_or_5(limit: int) -> int {
    def loop(acc: Any, num: Any) -> object {
        if (num < 1) {
            return acc;
        }
        if (((num % 3) == 0) or ((num % 5) == 0)) {
            return loop((acc + num), (num - 1));
        }
        return loop(acc, (num - 1));
    }
    return loop(0, (limit - 1));
}

