"""Essa funcao recebe duas assinaturas de texto e deve devolver o grau
    de similaridade entre as assinaturas.

    Args:
      main_sign: param text_sign:
      text_sign:

    Returns:
        float: Grau de similaridade entre as assinaturas
    """
def compara_assinatura(main_sign: list, text_sign: list) -> float {
    sign_calc = 0;
    for (i, _) in enumerate(main_sign) {
        sign_calc += abs((main_sign[i] - text_sign[i]));
    }
    return (sign_calc / 6);
}

"""Return a new sequence with segments at position pos1 and pos2 swapped.

    pos1, pos2 are both of the form (start1, end1), (start2, end2)
    """
def swap(seq: Any, pos1: Any, pos2: Any) -> object {
    ((start1, end1), (start2, end2)) = sorted([pos1, pos2]);
    return (
        seq[:start1]
        + seq[start2:end2]
        + seq[end1:start2]
        + seq[start1:end1]
        + seq[end2:]
    );
}

