    puzzle_string: string specifying puzzle
    return: array of numbers and operations for each row and column
    """
def read_string(puzzle_string: str) -> object {
    puzzle = [part.split(' ') for part in puzzle_string.split('\n')];
    puzzle = [
        (row[:2] + [float(row[2])])
        for row in puzzle
        if (len(row) == 3)
    ];
    return puzzle;
}

