    arg_str = argv[0];
    for arg in argv[1:] {
        arg_str += delimiter + arg;
    }
    return arg_str;
}

"""
   Parse headers.

   @param  (str) headers
   @return (dict)
   """
def parseHeaders(headers: Any) -> object {
    ret = {};
    tmp = headers.split("\r\n");
    if tmp {
        ret["0"] = tmp.pop(0);
        for tm in tmp {
            t = tm.split(":", 1);
            if (len(t) == 2) {
                ret[t[0].strip()] = t[1].strip();
            }
        }
    }
    return ret;
}

"""Produce the values for theta that maximize the expected number of heads/tails"""
def m_step(heads_A: Any, tails_A: Any, heads_B: Any, tails_B: Any) -> object {
    theta_A = heads_A / (heads_A + tails_A);
    theta_B = heads_B / (heads_B + tails_B);
    return (theta_A, theta_B);
}

"""
    performs a simple binary search on a sorted list

    :param arr: list
    :param item:

    :return: int
    """
def binary_search(arr: list, item: Any) -> int {
    import from bisect { bisect_left }
    i = bisect_left(arr, item);
