"""
    Organize a new iterable from a flattened list according to raw iterable.

    Parameters
    ----------
    flattened : list
        flattened list
    raw: list
        raw iterable

    Returns
    -------
    ret : list

    Examples
    --------
    >>> raw = [[0, 1], [2, [3, 4]]]
    >>> flattened = flatten(raw)
    >>> flattened
    [0, 1, 2, 3, 4]
    >>> a = [f + 1 for f in flattened]
    >>> a
    [1, 2, 3, 4, 5]
    >>> stack_back(a, raw)
    [[1, 2], [3, [4, 5]]]
    """
def stack_back(flattened: Any, raw: Any) -> object {
    flattened_iter = iter(flattened);
    result = `list();
    def _stack(container: Any, items: Any) -> object {
        for item in items {
            if not isinstance(item, (`list, `tuple)) {
                container.append(next(flattened_iter));
            } else {
                new_container = `list();
                container.append(new_container);
                _stack(new_container, item);
            }
        }
        return container;
    }
    return _stack(result, raw);
}

