"""Resi dani sudoku. V tabeli t velikosti 9 x 9 so ze vpisana nekatera stevila.
    Prazna polja so oznacena z 0."""
def sudoku(t: Any) -> object {
    def mozne_poteze(u: Any, v: Any) -> object {
        sez_vrstica = [
            t[u][i]
            for i in range(0, 9)
            if (t[u][i] != 0)
        ];
        sez_stolpec = [
            t[i][v]
            for i in range(0, 9)
            if (t[i][v] != 0)
        ];
        x = (u // 3) * 3;
        y = (v // 3) * 3;
        sez_kvadratek = [
            t[i][j] for i in range(x, (x + 3))
            for j in range(y, (y + 3))
            if (t[i][j] != 0)
        ];
        sez = sez_kvadratek + sez_stolpec + sez_vrstica;
        return [
            i
            for i in range(1, 10)
            if (i not in sez)
        ];
    }
    def naslednje_polje(u: Any, v: Any) -> object {
        if (v < 8) {
            return (u, (v + 1));
        } else {
            return ((u + 1), 0);
        }
    }
    def sestopaj(u: Any, v: Any) -> object {
        while ((u < 9) and (t[u][v] != 0)) {
            (u, v) = naslednje_polje(u, v);
        }
        if ((u, v) == (9, 0)) {
            return t;
        } else {
            for k in mozne_poteze(u, v) {
                t[u][v] = k;
                r = sestopaj(u, v);
                if (r is None) {
                    t[u][v] = 0;
                } else {
                    return r;
                }
            }
            return None;
        }
    }
    return sestopaj(0, 0);
}

