    Utilities to clean jinja template;

    Remove all ``|`` and `` `` until the last leading ``|``

    """
def until_ruler(doc: Any) -> object {
    lines = doc.split("\n");
    new = [];
    for l in lines {
        while ((len(l.lstrip()) >= 1) and (l.lstrip()[0] == "|")) {
