}

"""Return an index of `subseq`uence in the `seq`uence.

    Or `-1` if `subseq` is not a subsequence of the `seq`.

    The time complexity of the algorithm is O(n*m), where

        n, m = len(seq), len(subseq)

    >>> index([1,2], range(5))
    1
    >>> index(range(1, 6), range(5))
    -1
    >>> index(range(5), range(5))
    0
    >>> index([1,2], [0, 1, 0, 1, 2])
    3
    """
def index(subseq: Any, seq: Any) -> object {
    (i, n, m) = (-1, len(seq), len(subseq));
    try {
        while True {
            i = seq.index(subseq[0], (i + 1), ((n - m) + 1));
            if (subseq == seq[i:(i + m)]) {
                return i;
            }
        }
    } except ValueError {
        return -1;
    }
}

"""Get two's complement of `raw_val`.

        Args:
            raw_val (int): Raw value
            length (int): Max bit length

        Returns:
            int: Two's complement
        """
def getTwosComplement(raw_val: Any, length: Any) -> object {
    val = raw_val;
    if (raw_val & (1 << (length - 1))) {
        val = raw_val - (1 << length);
    }
    return val;
}

