    Perform a vertical flip (along the horizontal axis) of
    all the pairs in the network. Such a flip should result
    in a valid sorting network (provided the network used
    for the flip was valid itself).
    """
def vertical_flip(pairs: Any) -> object {
    max_idx = max(pairs, key=lambda (pair: Any) { pair[1]; })[1];
