    repository.
    Each of the dicts must have the following keys: `changeset_revisions`( if check revisions is true), `name`, `owner`, and
    (either `tool_shed` or `tool_shed_url`).
    """
def the_same_repository(
    repo_1_info: Any, repo_2_info: Any, check_revision: Any = True
) -> object {
    if (
        not check_revision
        or (
            repo_1_info.get('changeset_revision')
            == repo_2_info.get('changeset_revision')
        )
    ) {
        if (repo_1_info.get('name') == repo_2_info.get('name')) {
            if (repo_1_info.get('owner') == repo_2_info.get('owner')) {
                t1ts = repo_1_info.get(
                    'tool_shed', repo_1_info.get('tool_shed_url', None)
                );
                t2ts = repo_2_info.get(
                    'tool_shed', repo_2_info.get('tool_shed_url', None)
                );
                if ((t1ts in t2ts) or (t2ts in t1ts)) {
                    return True;
                }
            }
        }
    }
    return False;
}

"""
    Starting with the number 1 and moving to the right in a clockwise direction a 5 by 5 spiral is formed as follows:
    21 22 23 24 25
    20  7  8  9 10
    19  6  1  2 11
    18  5  4  3 12
    17 16 15 14 13
    It can be verified that the sum of the numbers on the diagonals is 101.
    What is the sum of the numbers on the diagonals in a 1001 by 1001 spiral formed in the same way?
    """
def euler_problem_28(n: Any = 1001) -> object {
    def sum_corners(side_length: Any) -> object {
        assert ((side_length % 2) == 1);
        if (side_length == 1) {
            return 1;
        }
        return (
            4
            * int(
                (((side_length ** 2) * (5 / 8)) + (((side_length - 2) ** 2) * (3 / 8)))
            )
        );
    }
    total = 0;
    for k in range(1, (n + 1), 2) {
        total += sum_corners(k);
    }
    return total;
}

