"""
    Calculates hamming distance between two sim hashes.
    :param sim_hash_one: long - sim hash
    :param sim_hash_two: long - sim hash
    :return: (int) returns hamming distance.
    """
def hash_distance(sim_hash_one: Any, sim_hash_two: Any) -> object {
    f = 128;
    x = (sim_hash_one ^ sim_hash_two) & ((1 << f) - 1);
    ans = 0;
    while x {
        ans += 1;
        x &= x - 1;
    }
    return ans;
}

"""
        Retreive the class name associate to the generic `a_class_name'.
        The Generics of the class is `a_class_generics' and the classes
        associate to the generics are in `a_object_generics'.
    """
def translate_generics_to_class(
    a_class_generics: Any, a_object_generics: Any, a_class_name: Any
) -> object {
    l_object_generics = a_object_generics.replace(" ", "").replace("\t", "").split(",");
    l_result = None;
    i = 0;
    while ((i < len(a_class_generics)) and (a_class_generics[i] != a_class_name)) {
        i = i + 1;
    }
    l_result = None;
    if (i < len(l_object_generics)) {
        l_result = l_object_generics[i];
    }
    return l_result;
}

