""" bubble sort implementation

    >>> bubblesort([6, 4, 8, 2, 1, 9, 10])
    [1, 2, 4, 6, 8, 9, 10]
    """
def bubblesort(a: Any) -> object {
    for i in range(len(a)) {
        for j in range(i, len(a)) {
            if (a[i] > a[j]) {
                (a[i], a[j]) = (a[j], a[i]);
            }
        }
    }
    return a;
}

