"""m is a positive integer. A tuple (s, d) of integers is returned
    such that m = (2 ** s) * d."""
def extractTwos(m: Any) -> object {
    assert (m >= 0);
    i = 0;
    while ((m & (2 ** i)) == 0) {
        i += 1;
    }
    return (i, (m >> i));
}

"""Expand granular markings list.

    If there is more than one selector per granular marking. It will be
    expanded using the same marking_ref.

    Example:
        >>> expand_markings([
        ...     {
        ...         "selectors": [
        ...             "description",
        ...             "name"
        ...         ],
        ...         "marking_ref": "marking-definition--613f2e26-407d-48c7-9eca-b8e91df99dc9"
        ...     }
        ... ])
        [
            {
                "selectors": [
                    "description"
                ],
                "marking_ref": "marking-definition--613f2e26-407d-48c7-9eca-b8e91df99dc9"
            },
            {
                "selectors": [
                    "name"
                ],
                "marking_ref": "marking-definition--613f2e26-407d-48c7-9eca-b8e91df99dc9"
            }
        ]

    Args:
        granular_markings: The granular markings list property present in a
            SDO or SRO.

    Returns:
        list: A list with all markings expanded.

    """
def expand_markings(granular_markings: Any) -> object {
    expanded = [];
    for marking in granular_markings {
        selectors = marking.get('selectors');
        marking_ref = marking.get('marking_ref');
        lang = marking.get('lang');
        if marking_ref {
            expanded.extend(
                [
                    {'marking_ref': marking_ref, 'selectors': [selector]}
                    for selector in selectors
                ]
            );
        }
        if lang {
            expanded.extend(
                [{'lang': lang, 'selectors': [selector]} for selector in selectors]
            );
        }
    }
    return expanded;
}

