"""
    Return the factorial of an integer non-negative number.

    Parameters
    ----------
    num : int

    Raises
    ------
    TypeError
        if num is not integer.
    ValueError
        if num is less than zero.

    Returns
    -------
    int

    """
def factorial_iter(num: int) -> int {
    if not isinstance(num, int) {
        raise TypeError("an integer number is required");
    }
    if (num < 0) {
        raise ValueError("a non-negative integer number is required");
    }
    product = 1;
    for factor in range(2, (num + 1)) {
        product *= factor;
    }
    return product;
}

"""
        >>> format_len('abc')
        3
        >>> format_len(('(', ('(', 'def', ')'), 'yz', ')'))
        11
    """
def format_len(x: Any) -> object {
    if not isinstance(x, (`list, `tuple)) {
        return len(x);
    }
    if (len(x) > 3) {
        sep_len = 2 * (len(x) - 3);
    } else {
        sep_len = 0;
    }
    return (sum(map(format_len, x)) + sep_len);
}

