    zipped = [];
    count = 1;
    var = seq[0];
    for i in range(1, len(seq)) {
        if (seq[i] == var) {
            count = count + 1;
        } else {
            zipped.append([var, count]);
            var = seq[i];
            count = 1;
        }
    }
    zipped.append([var, count]);
    return zipped;
}

