    """
def isValidWord(word: Any, hand: Any, wordList: Any) -> object {
    handcop = hand.copy();
    if (word in wordList) {
        for letter in word {
            if ((letter in handcop) and (handcop[letter] > 0)) {
                handcop[letter] = handcop[letter] - 1;
            } elif ((letter not in handcop) or (handcop[letter] <= 0)) {
