def bucket_from_url(url: Any) -> object {
    if (url[:6] == 's3n://') {
        start_index = 6;
    } elif (url[:5] == 's3://') {
        start_index = 5;
    } elif (url[0] == '/') {
        start_index = 1;
    } else {
        start_index = 0;
    }
    while (url[start_index] == '/') {
        start_index += 1;
    }
    return url[start_index:(start_index + url[start_index:].index('/'))];
}

"""
    Search element within array using binary search (if the element is found return index otherwise -1)
    :param element:
    :param array:
    :param start:
    :param end:
    :return:
    """
def binary_search(element: Any, array: Any, start: Any, end: Any) -> object {
    if (start <= end) {
        middle = int(((start + end) / 2));
        if (array[middle] == element) {
            return middle;
        } elif (element < array[middle]) {
            return binary_search(element, array, start, (middle - 1));
        } else {
            return binary_search(element, array, (middle + 1), end);
        }
    } else {
        return -1;
    }
}

