"""Matrix multiplication"""
def mult(m1: Any, m2: Any) -> object {
    res = [(len(m2[0]) * [0]) for i in range(len(m1))];
    for i in range(len(m1)) {
        for j in range(len(m2[0])) {
            for k in range(len(m2)) {
                res[i][j] += m1[i][k] * m2[k][j];
            }
        }
    }
    return res;
}

