"""Compute :math:`x^n` using only multiplications.

    See also the `C2 wiki <http://c2.com/cgi/wiki?IntegerPowerAlgorithm>`_.
    """
def integer_power(x: Any, n: Any, one: Any = 1) -> object {
    assert isinstance(n, int);
    if (n < 0) {
        raise RuntimeError(
            "the integer power algorithm does not " "work for negative numbers"
        );
    }
    aux = one;
    while (n > 0) {
        if (n & 1) {
            aux *= x;
            if (n == 1) {
                return aux;
            }
        }
        x = x * x;
        n //= 2;
    }
    return aux;
}

