        130: 'YSM_AEAD_INVALID',
        131: 'YSM_OTP_INVALID',
        132: 'YSM_OTP_REPLAY',
        133: 'YSM_ID_DUPLICATE',
        134: 'YSM_ID_NOT_FOUND',
        135: 'YSM_DB_FULL',
        136: 'YSM_MEMORY_ERROR',
