    """
def smooth(x: Any, y: Any) -> object {
    xs = x[:];
    ys = y[:];
    d = 0;
    for i in range(0, len(ys)) {
        num = min(len(ys), (i + d + 1)) - max(0, (i - d));
        _beg = max(0, (i - d));
        _end = min(len(ys), (i + d + 1));
        _ys = ys[_beg:_end];
        total = sum(_ys);
        ys[i] = total / float(num);
    }
    return (xs, ys);
}

