"""
    Matches to any of the specified arguments with == operator
    """
def any_of(*args: Any) -> object {
    class AnyOfMatcher {
        def init(self: AnyOfMatcher, values: Any) -> object {
            self.values = values;
        }
        def __eq__(self: AnyOfMatcher, other: Any) -> object {
            return `any(map(lambda (v: Any) { (v == other); }, self.values));
        }
        def __ne__(self: AnyOfMatcher, other: Any) -> object {
            return all(map(lambda (v: Any) { (v != other); }, self.values));
        }
    }
    if not args {
        raise ValueError("at least one argument should be provided for any_of matcher");
    }
    return AnyOfMatcher(args);
}

