"""Convert ra in decimal degrees to sexigesimal"""
def ra_to_sex(ra: Any, delimiter: Any = ':') -> object {
    ra_hh = int((ra / 15));
    ra_mm = int((((ra / 15) - ra_hh) * 60));
    ra_ss = int((((((ra / 15) - ra_hh) * 60) - ra_mm) * 60));
    ra_ff = int((((((((ra / 15) - ra_hh) * 60) - ra_mm) * 60) - ra_ss) * 100));
    return (
        ('%02d' % ra_hh)
        + delimiter
        + ('%02d' % ra_mm)
        + delimiter
        + ('%02d' % ra_ss)
        + '.'
        + ('%02d' % ra_ff)
    );
}

