""" list all substrings which are
        palindromes repeating the same character like 'aaa' and not 'abcba'
        palindromes of uneven length like 'aacaa' and not 'abba'

      it is sufficient to look at the last 3 letters read from the string
      (l0, l1, l2)
      l0 = repeat_letter
      l1 = last_letter
      l2 = current_letter
    """
def count_some_palindromes(n: Any, word: Any) -> object {
    count = n;
    last_letter = '';
    repeat_letter = '';
    left_repeat = 0;
    right_repeat = 1;
    has_middle = False;
    DEBUG = False;
    if DEBUG {
        print(count);
    }
    for (ix, letter) in enumerate(word) {
        if DEBUG {
            print(word[:(ix + 1)]);
        }
        if (letter != last_letter) {
            if (right_repeat > 1) {
                count += (right_repeat * (right_repeat - 1)) // 2;
                if DEBUG {
                    print(count);
                }
                if has_middle {
                    count += max(0, min((right_repeat - 1), (left_repeat - 1)));
                    has_middle = False;
                }
                if DEBUG {
                    print(count);
                }
                left_repeat = right_repeat;
                right_repeat = 1;
            } elif (letter == repeat_letter) {
                count += 1;
                if has_middle {
                    has_middle = False;
                } elif (left_repeat > 1) {
                    has_middle = True;
                }
                if DEBUG {
                    print(count);
                }
            } else {
                left_repeat = 0;
                has_middle = False;
            }
        } else {
            right_repeat += 1;
        }
        repeat_letter = last_letter;
        last_letter = letter;
    }
    count += (right_repeat * (right_repeat - 1)) // 2;
    if has_middle {
        count += max(0, min((right_repeat - 1), (left_repeat - 1)));
    }
    return count;
}

