""" Returns the maximal product of positive and (odd) negative numbers."""
def calculate_max_power(panel_array: Any) -> object {
    if (len(panel_array) == 0) {
        return 0;
    }
    positive_panels = `list(filter(lambda (x: Any) { (x > 0); }, panel_array));
    positive_product = 1;
    for x in positive_panels {
        positive_product *= x;
    }
    negative_panels = sorted(`list(filter(lambda (x: Any) { (x < 0); }, panel_array)));
    if ((len(negative_panels) == 1) and (len(positive_panels) == 0)) {
        return negative_panels[0];
    }
    zero_panels = sorted(`list(filter(lambda (x: Any) { (x == 0); }, panel_array)));
    if (len(zero_panels) == len(panel_array)) {
        return 0;
    }
    if ((len(negative_panels) % 2) != 0) {
        negative_panels.pop();
    }
    negative_product = 1;
    for x in negative_panels {
        negative_product *= x;
    }
    return (negative_product * positive_product);
}

""" Compares two paths to verify whether they're the same.
    :param path1: list of nodes.
    :param path2: list of nodes.
    :return: boolean.
    """
def same(path1: Any, path2: Any) -> object {
    start1 = path2.index(path1[0]);
    checks = [
        (path1[:(len(path1) - start1)] == path2[start1:]),
        (path1[(len(path1) - start1):] == path2[:start1])
    ];
    if all(checks) {
        return True;
    }
    return False;
}

"""Calculates the probability for a single
    event to happen in a list of possibilities.

    Args:
        event

        possibilities (list)

    Returns:
         float: The probability"""
def __single_random_event(event: Any, possibilities: Any) -> object {
    if (len(possibilities) == 0) {
        return 0;
    }
    matches = 0;
    for possibility in possibilities {
        if (event == possibility) {
            matches += 1;
        }
    }
    return (matches / len(possibilities));
}

