"""
    Since the activities are sorted by finish time, we can solve the problem in O(n) time
    """
def max_activities(start: list, end: list) -> int {
    return_value: int = 1;
    index: int = 1;
    length: int = len(start);
    prev_index: int = 0;
    while (index < length) {
        if (start[index] >= end[prev_index]) {
            return_value += 1;
            prev_index = index;
        }
        index += 1;
    }
    return return_value;
}

