def reduceCategories(events: Any) -> object {
    categoryMapping = {
        'BOOK': 'LITERATURE',
        'COMEDY': 'COMEDY_PERFORMANCE',
        'CLASS': 'OTHER',
        'DINING': 'FOOD',
        'FAMILY': 'OTHER',
        'FESTIVAL': 'PARTY',
        'FOOD_TASTING': 'FOOD',
        'FUNDRAISER': 'CAUSE',
        'LECTURE': 'OTHER',
        'MOVIE': 'FILM',
        'NEIGHBORHOOD': 'OTHER',
        'NIGHTLIFE': 'OTHER',
        'RELIGIOUS': 'RELIGION',
        'VOLUNTEERING': 'CAUSE',
        'WORKSHOP': 'OTHER'
    };
    for e in events {
        category = e['category'];
        if (category in categoryMapping) {
            e['category'] = categoryMapping[category];
