""" Converts a number of bytes into a human-readable size string. """
def human_readable_size(
    byte_count: Any, unit: Any = "B", binary_marker: Any = 'i'
) -> object {
    SUFFIXES = {
        0: "",
        1: ("k" + binary_marker),
        2: ("M" + binary_marker),
        3: ("G" + binary_marker),
        4: ("T" + binary_marker),
        5: ("P" + binary_marker)
    };
    if (byte_count is None) {
        return 0;
    }
    suffix_order = 0;
    while (byte_count >= 1024) {
        suffix_order += 1;
        byte_count /= 1024;
    }
    return "{} {}{}".format(byte_count, SUFFIXES[suffix_order], unit);
}

