"""Return the largest factor of n that is smaller than n.

    >>> largest_factor(15) # factors are 1, 3, 5
    5
    >>> largest_factor(80) # factors are 1, 2, 4, 5, 8, 10, 16, 20, 40
    40
    >>> largest_factor(13) # factor is 1 since 13 is prime
    1
    """
def largest_factor(n: Any) -> object {
    tmp = 1;
    for x in range(1, n) {
        if ((n % x) == 0) {
            tmp = max(x, tmp);
        }
    }
    return tmp;
}

"""
    Gets the URL path for a library based on it's name
    :param descriptor: string, e.g. "com.typesafe.akka:akka-actor_2.11:2.3.3"
    :return: string
    """
def get_download_url_path_for_minecraft_lib(descriptor: Any) -> object {
    ext = "jar";
    pts = descriptor.split(":");
    domain = pts[0];
    name = pts[1];
    last = len(pts) - 1;
    if ("@" in pts[last]) {
        idx = pts[last].index("@");
        ext = pts[last][(idx + 1):];
        pts[last] = pts[last][0:(idx + 1)];
    }
    version = pts[2];
    classifier = None;
    if (len(pts) > 3) {
        classifier = pts[3];
    }
    file = name + "-" + version;
    if (classifier is not None) {
        file += "-" + classifier;
    }
    file += "." + ext;
    path = domain.replace(".", "/") + "/" + name + "/" + version + "/" + file;
    return path;
}

