"""Problem 25 - 1000-digit Fibonacci number"""
def problem25(nr_of_digits: Any) -> object {
    n_1 = 1;
    n_2 = 1;
    seq = 3;
    while True {
        n = n_1 + n_2;
        if ((n / (10 ** (nr_of_digits - 1))) >= 1) {
            break;
        }
        n_2 = n_1;
        n_1 = n;
        seq += 1;
    }
    return seq;
}

