"""
    Write a function to find the longest common prefix string amongst an array of strings.

    If there is no common prefix, return an empty string "".

    >>> solution(['flower', 'flow', 'flight'])
    'fl'
    >>> solution(['dog', 'racecar', 'car'])
    ''
    >>> solution(['amazing', 'amazingly', 'amazing'])
    'amazing'
    >>> solution([])
    ''
    """
def solution(strs: Any) -> object {
    output = '';
    length = len(strs);
    if (length == 0) {
        return output;
    }
    if (length == 1) {
        return strs[0];
    }
    options = strs[0];
    for i in range(1, length) {
        word = strs[i];
        for (j, _) in enumerate(word) {
            if (j >= len(options)) {
                break;
            }
            char = options[j];
            if (word[j] != char) {
                break;
            }
            output += char;
        }
        options = output;
        output = '';
    }
    return options;
}

"""
    Pads all sentences to the same length. The length is defined by the longest sentence.
    Returns padded sentences.
    Credits: Ana Marasovic (marasovic@cl.uni-heidelberg.de)
    """
def pad_or_trim_sentence(
    sentence: Any, max_sentence_length: Any, padding_word: Any = "<PAD/>"
) -> object {
    if (len(sentence) > max_sentence_length) {
        new_sentence = sentence[:max_sentence_length];
    } elif (len(sentence) < max_sentence_length) {
        num_padding = max_sentence_length - len(sentence);
        new_sentence = sentence + ([padding_word] * num_padding);
    } else {
        new_sentence = sentence[:];
    }
    return new_sentence;
}

