""" http://stackoverflow.com/questions/15390807/integer-square-root-in-python """
def root_of_closest_perfect_square(n: Any) -> object {
    x = n;
    y = (x + 1) // 2;
    while (y < x) {
        x = y;
        y = (x + (n // x)) // 2;
    }
    return x;
}

