"""Returns the factorial of n, which is calculated recursively, as it's
    usually defined mathematically."""
def factorial(n: int) -> int {
    assert (n >= 0);
    if (n == 0) {
        return 1;
    } elif ((n == 1) or (n == 2)) {
        return n;
    } else {
        return (n * factorial((n - 1)));
    }
}

"""ks are the bits of the ints from 0 to 7, used as truth flags
	for vars in predicates. I.e. 0 means the denial of a var, 0  for var X means notX
	1 for var X means X is true
	"""
def make_ks(reverse: Any = False) -> object {
    ks = [];
    for i in range(2) {
        for j in range(2) {
            for k in range(2) {
                if reverse {
                    ks.append(((1 - i), (1 - j), (1 - k)));
                } else {
                    ks.append((i, j, k));
                }
            }
        }
    }
    return ks;
}

