    :type num_words: int
    :param vocabulary: vocabulary
    :type vocabulary: list(unicode)
    :return: list of num_words words from vocabulary
    :rtype: list(unicode)
    """
def topic_render(topic: Any, num_words: Any, vocabulary: Any) -> object {
    indices = topic[0];
    terms = [];
    for i in range(num_words) {
