"""

    Parameters
    ----------
    n : int
        number of steps

    Returns
    -------
    int
        number of ways a child can run a stairs

    >>> bottom_up_staircase_problem(4)
    7

    >>> bottom_up_staircase_problem(0)
    1
    """
def bottom_up_staircase_problem(n: Any) -> object {
    cache = [0 for _ in range((n + 1))];
    cache[0] = 1;
    strides = [1, 2, 3];
    i = 1;
    while (i <= n) {
        for stride in strides {
            if (stride <= i) {
                cache[i] += cache[(i - stride)];
            }
        }
        i += 1;
    }
    return cache[n];
}

"""Compute the coordinates of inner and outer equatorial points and high
