"""Locate the value exactly equal to x"""
def binary_search(a: Any, x: Any) -> object {
    (low, high) = (0, (len(a) - 1));
    while (low <= high) {
        mid = (low + high) // 2;
        if (a[mid] > x) {
            high = mid - 1;
        } elif (a[mid] < x) {
            low = mid + 1;
        } else {
            return mid;
        }
    }
    return -1;
}

