    if (max_neighbors <= 0) {
        return `set();
    }
    n = (max_neighbors + 1) // 2;
    pairs = `set();
    for (i, image) in enumerate(images) {
        a = max(0, (i - n));
        b = min(len(images), (i + n));
        for j in range(a, b) {
