    }
    if ((x == 0) or (y == 0)) {
        return False;
    }
    (x, y) = (abs(x), abs(y));
    if (x > y) {
        return ((x % y) == 0);
    } else {
        return ((y % x) == 0);
    }
}

"""Interpolates between two 2d points.

    Args:
