"""Determine if ancestor_repository_dependencies is the same as or a subset of current_repository_dependencies."""
def compare_repository_dependencies(
    ancestor_repository_dependencies: Any, current_repository_dependencies: Any
) -> object {
    if (
        len(ancestor_repository_dependencies) <= len(current_repository_dependencies)
    ) {
        for ancestor_tup in ancestor_repository_dependencies {
            (
                ancestor_tool_shed,
                ancestor_repository_name,
                ancestor_repository_owner,
                ancestor_changeset_revision
            ) = ancestor_tup;
            found_in_current = False;
            for current_tup in current_repository_dependencies {
                (
                    current_tool_shed,
                    current_repository_name,
                    current_repository_owner,
                    current_changeset_revision
                ) = current_tup;
                if (
                    (current_tool_shed == ancestor_tool_shed)
                    and (current_repository_name == ancestor_repository_name)
                    and (current_repository_owner == ancestor_repository_owner)
                    and (current_changeset_revision == ancestor_changeset_revision)
                ) {
                    found_in_current = True;
                    break;
                }
            }
            if not found_in_current {
                return 'not equal and not subset';
            }
        }
        if (
            len(ancestor_repository_dependencies)
            == len(current_repository_dependencies)
        ) {
            return 'equal';
        } else {
            return 'subset';
        }
    }
    return 'not equal and not subset';
}

