    Output:
           desc - next integer in descending order, e.g. [6]
           desc + descending(x) + ... - a list of integers in descending order, e.g. [6,5,3,2,1,0]
    """
def descending(x: Any) -> object {
    if (len(x) == 0) {
        return [];
    } else {
        mx = max(x);
        desc = [mx];
        x.remove(mx);
    }
    return (desc + descending(x));
}

