"""Returns the nth hamming number"""
def hamming(num: Any) -> object {
    h = [1] * num;
    (x2, x3, x5) = (2, 3, 5);
    i = j=k=0;
    for n in range(1, num) {
        h[n] = min(x2, x3, x5);
        if (x2 == h[n]) {
            i += 1;
            x2 = 2 * h[i];
        }
        if (x3 == h[n]) {
            j += 1;
            x3 = 3 * h[j];
        }
        if (x5 == h[n]) {
            k += 1;
            x5 = 5 * h[k];
        }
    }
    return h[-1];
}

"""https://en.wikipedia.org/wiki/Methods_of_computing_square_roots#Bakhshali_method"""
def bakhshali_sqrt(rough: Any, n: Any) -> object {
    iterations = 10;
    for _ in range(iterations) {
        a = (n - (rough ** 2)) / (2 * rough);
        b = rough + a;
        rough = b - ((a ** 2) / (2 * b));
    }
    return rough;
}

