    ...         p2a = [0] * len(p2)
    ...         for i, oi in enumerate(p1):
    ...             p2a[wtm[i]] = oi
    ...         assert p2 == p2a
    """
def get_write_to_map_from_permutation(original: Any, permuted: Any) -> object {
